#!/usr/bin/env python3
from pwn import *

# Configuration
host = 'rev.chal.csaw.io'
port = 8000
key = "aaGr6xly5gT42"
addresses = ["0x407a30", "0x6e1140"]

def try_combination(r, addr):
    try:
        # Send the address and key
        r.sendline(f"{addr} {key}".encode())
        # Get the response with a timeout
        response = r.recvall(timeout=5)
        return response.decode('utf-8', errors='ignore')
    except Exception as e:
        return f"Error: {str(e)}"

# Test remote connection
for addr in addresses:
    print(f"\nTrying address {addr}")
    try:
        r = remote(host, port)
        result = try_combination(r, addr)
        print(f"Response: {result}")
        r.close()
    except Exception as e:
        print(f"Connection failed: {str(e)}")

